  leftArm: THREE.Group;
  rightArm: THREE.Group;
  leftLeg: THREE.Group;
  rightLeg: THREE.Group;
  /** Hand anchor inside the right arm — the held item model goes here. */
  itemHolder: THREE.Group;
  materials: THREE.Material[];
  geometries: THREE.BufferGeometry[];
};

