const HAIR = 0x4a3220;
const SHIRT = 0x2e8b83;
const PANTS = 0x3b3f8f;
const SHOES = 0x4a3527;
const EYE_WHITE = 0xffffff;
const EYE_PUPIL = 0x2b2b45;

