    this.scene.add(this.worldMesh);
    this.scene.add(this.camera);

    this.heldItem = createHeldItemView(this.camera);
    this.crackOverlay = createCrackOverlay(this.scene);
    this.mobVisuals = createMobVisuals(this.scene);
  }

