import { describe, expect, test } from "bun:test";
import * as THREE from "three";
import { cameraOffsetDirection, computeCameraPose } from "@/lib/game/render/cameraView";

const scratch = new THREE.Vector3();

describe("cameraOffsetDirection", () => {
  test("rear points opposite the look direction, front along it", () => {
    // yaw 0, pitch 0: the player looks along -Z.
    expect(cameraOffsetDirection("third-rear", 0, 0, scratch).toArray()).toEqual([-0, -0, 1]);
    expect(cameraOffsetDirection("third-front", 0, 0, scratch).toArray()).toEqual([-0, 0, -1]);
  });

  test("looking up drops the rear camera below the look axis", () => {
    const dir = cameraOffsetDirection("third-rear", 0, Math.PI / 4, scratch);
    expect(dir.y).toBeLessThan(0);
    expect(dir.z).toBeGreaterThan(0);
  });
});

describe("computeCameraPose", () => {
  test("first person is the eye itself with passthrough rotation", () => {
    const pose = computeCameraPose("first", 1, 2, 3, 0.5, -0.3, 99, scratch);
    expect([pose.posX, pose.posY, pose.posZ]).toEqual([1, 2, 3]);
    expect(pose.yaw).toBe(0.5);
    expect(pose.pitch).toBe(-0.3);
  });

  test("rear sits behind the eye and keeps the player's view direction", () => {
    const pose = computeCameraPose("third-rear", 0, 10, 0, 0, 0, 4, scratch);
    expect(pose.posZ).toBeCloseTo(4);
    expect(pose.posY).toBeCloseTo(10);
    expect(pose.yaw).toBe(0);
    expect(pose.pitch).toBe(0);
  });

  test("front sits ahead, flips the heading, and inverts the tilt", () => {
    const pose = computeCameraPose("third-front", 0, 10, 0, 0.5, 0.4, 4, scratch);
    const lookX = -Math.cos(0.4) * Math.sin(0.5) * 4;
    const lookZ = -Math.cos(0.4) * Math.cos(0.5) * 4;
    expect(pose.posX).toBeCloseTo(lookX);
    expect(pose.posY).toBeCloseTo(10 + Math.sin(0.4) * 4);
    expect(pose.posZ).toBeCloseTo(lookZ);
    expect(pose.yaw).toBeCloseTo(0.5 + Math.PI);
    expect(pose.pitch).toBeCloseTo(-0.4);
  });

  test("a clamped distance pulls the camera proportionally closer", () => {
    const far = computeCameraPose("third-rear", 0, 10, 0, 0, 0, 4, scratch);
    const near = computeCameraPose("third-rear", 0, 10, 0, 0, 0, 1.5, scratch);
    expect(near.posZ).toBeCloseTo((far.posZ * 1.5) / 4);
  });
});

import { useState } from "react";
import type { AudioSettings } from "@/lib/game/audio/audioDirector";

type PauseMenuProps = {
  saveMessage: string;
  audioSettings: AudioSettings;
  onAudioSettingsChange: (partial: Partial<AudioSettings>) => void;
  onBack: () => void;
  onSave: () => void;
  onLoad: () => void;
  onReset: () => void;
};

const CONTROLS: Array<[string, string]> = [
  ["Move / Jump", "W A S D / Space"],
  ["Sprint / Crouch", "W + CapsLock / C"],
  ["Mine / Attack", "Hold left click / Left click"],
  ["Place block", "Right click or E"],
  ["Inventory", "I"],
  ["Eat food", "F"],
  ["Hotbar", "1-9"],
  ["Debug overlay", "F3"],
  ["Emergency unstuck", "U"]
];

/**
 * The Minecraft-style game menu: shown while the engine is paused, with the
 * classic column of gray beveled buttons over a dimmed (frozen) world.
 */
export default function PauseMenu({ saveMessage, audioSettings, onAudioSettingsChange, onBack, onSave, onLoad, onReset }: PauseMenuProps) {
  const [confirmingReset, setConfirmingReset] = useState(false);

  const volumeSlider = (label: string, value: number, onValue: (volume: number) => void) => (
    <label className="pause-sound-row">
      <span>{label}</span>
      <input
        className="mc-slider"
        type="range"
        min={0}
        max={100}
        value={Math.round(value * 100)}
        onChange={(event) => onValue(Math.max(0, Math.min(1, Number(event.target.value) / 100)))}
        aria-label={`${label} volume`}
      />
    </label>
  );

  return (
    <div className="pause-overlay">
      <div className="pause-menu">
        <div className="pause-title">Game Menu</div>
        <button className="mc-button" onClick={onBack}>
          Back to Game
        </button>
        <button className="mc-button" onClick={onSave}>
          Save Game
        </button>
        <button className="mc-button" onClick={onLoad}>
          Load Save
        </button>
        {confirmingReset ? (
          <div className="pause-reset-row">
            <button className="mc-button danger" onClick={onReset}>
              Confirm Reset
            </button>
            <button className="mc-button" onClick={() => setConfirmingReset(false)}>
              Cancel
            </button>
          </div>
        ) : (
          <button className="mc-button" onClick={() => setConfirmingReset(true)}>
            Reset World
          </button>
        )}
        <div className="pause-sound">
          {volumeSlider("Sound", audioSettings.master, (volume) => onAudioSettingsChange({ master: volume }))}
          {volumeSlider("Music", audioSettings.music, (volume) => onAudioSettingsChange({ music: volume }))}
          <button className="mc-button" aria-pressed={audioSettings.muted} onClick={() => onAudioSettingsChange({ muted: !audioSettings.muted })}>
            {audioSettings.muted ? "Unmute Sound" : "Mute Sound"}
          </button>
        </div>
        {saveMessage && <div className="pause-save-message">{saveMessage}</div>}
        <div className="pause-controls">
          {CONTROLS.map(([action, keys]) => (
            <div key={action} className="pause-controls-row">
              <span>{action}</span>
              <span>{keys}</span>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

