  {
    id: "default",
    label: "Steve",
    palette: { skin: 0xc68e63, hair: 0x4a3220, shirt: 0x2e8b83, pants: 0x3b3f8f, shoes: 0x4a3527, eyeWhite: 0xffffff, eyePupil: 0x2b2b45 }
